-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (8856, 19, 'Anonymisierte Bewerbungsverfahren einführen und fördern (Bund)', 'Setzt an der Vorauswahl an, in der etwa Name oder Kopftuchfoto zu Absagen führen; das deutsche Pilotprojekt fand bessere Einladungschancen, ein französisches Feldexperiment dagegen Nachteile für Minderheiten.', 'gemischt', 'https://www.povertyactionlab.org/evaluation/cv-anonymes', 'bund', null, true, 'blind'),
  (8857, 19, 'Gleichbehandlungsgesetz reformieren: längere Fristen, Verbandsklage, Schutz vor staatlicher Diskriminierung (Bund)', 'Längere Fristen und Verbandsklage erleichtern die Durchsetzung bei Bewerbung und gegenüber Behörden; Wirkung auf die Häufigkeit von Diskriminierung kaum untersucht, Bundeskompetenz für Landesbehörden begrenzt.', 'offen', null, 'bund', null, true, 'blind'),
  (8858, 19, 'Antidiskriminierungsstelle des Bundes und Beratungsangebote für Betroffene ausbauen (Bund)', 'Mehr Beratung hilft Betroffenen, Rechte durchzusetzen, lindert aber vor allem Folgen; auf verbreitete Vorurteile wirkt sie nur mittelbar, Wirkungsstudien fehlen.', 'offen', null, 'bund', null, true, 'blind'),
  (8859, 19, 'Antidiskriminierungs-Fortbildungen für Beschäftigte von Behörden fördern oder vorschreiben (Bund)', 'Für eigene Behörden leicht umsetzbar; Meta-Analysen zeigen stabile Wissenszuwächse, aber schwache und abklingende Effekte auf Einstellungen und Verhalten.', 'gemischt', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'bund', null, true, 'blind'),
  (8860, 19, 'Diskriminierungsverbot in Art. 3 GG um sexuelle und geschlechtliche Identität erweitern (Bund)', 'Rechtliche Gleichstellung kann Normen und Einstellungen verschieben, Schutz besteht aber schon über Art. 3 Abs. 1 GG; Verfassungsänderung braucht Zweidrittelmehrheiten in Bundestag und Bundesrat.', 'gemischt', 'https://www.mcgill.ca/newsroom/node/158154', 'bund', null, true, 'blind'),
  (8861, 19, 'Bundesaktionsplan gegen Queerfeindlichkeit umsetzen und finanzieren (Bund)', 'Bündelt Akzeptanz-, Bildungs- und Beratungsmaßnahmen und ist finanzierbar; die Wirkung hängt von den Einzelmaßnahmen ab und ist kaum evaluiert.', 'offen', null, 'bund', null, true, 'blind'),
  (8862, 19, 'Familien- und Abstammungsrecht für Regenbogenfamilien gleichstellen (Bund)', 'Beseitigt eine konkrete rechtliche Benachteiligung, Bund ist zuständig; Studien zur Ehe-Öffnung zeigen schneller sinkende Vorurteile, teils aber Gegenreaktionen.', 'gemischt', 'https://www.mcgill.ca/newsroom/node/158154', 'bund', null, true, 'blind'),
  (8863, 19, 'Landesantidiskriminierungsgesetz einführen oder ausbauen, mit gestärkter Ombudsstelle (Land)', 'Schließt direkt die Schutzlücke gegenüber Behörden und Schulen; das erste Bundesland mit Gesetz verzeichnet tausende Anfragen und viele Schlichtungen, eine Wirkungsevaluation fehlt.', 'offen', 'https://www.berlin.de/sen/asgiva/presse/pressemitteilungen/2026/pressemitteilung.1670019.php', 'land', null, true, 'blind'),
  (8864, 19, 'Landesantidiskriminierungsgesetz aufheben oder einschränken (Land)', 'Rechtlich möglich, vergrößert aber die Schutzlücke gegenüber staatlichem Handeln, statt sie zu schließen.', 'offen', null, 'land', null, true, 'blind'),
  (8865, 19, 'Unabhängige Beschwerde- und Ombudsstellen für Diskriminierung durch Schulen, Polizei und Behörden (Land)', 'Gibt Betroffenen einen Weg gegen staatliche Diskriminierung; Erfahrungen mit Polizeibeauftragten zeigen Wirkung nur mit Ermittlungsbefugnissen und gezielter Ansprache Betroffener.', 'gemischt', 'https://www.humanistische-union.de/publikationen/vorgaenge/237-238-vorgaenge/publikation/unabhaengige-polizeibeauftragte-in-deutschland-auf-dem-weg-zum-standard-ziele-praktiken-defizite-und-moegliche-beitraege-zum-diskriminierungsschutz/', 'land', null, true, 'blind'),
  (8866, 19, 'Antidiskriminierungsstelle und Beauftragte des Landes abbauen (Land)', 'Spart Mittel und ist rechtlich möglich, nimmt Betroffenen aber Anlaufstellen gegen Diskriminierung durch staatliche Stellen.', 'offen', null, 'land', null, true, 'blind'),
  (8867, 19, 'Antidiskriminierungs-Ansprechpersonen in Schulen, Behörden und Polizei (Land)', 'Niedrigschwellige Anlaufstelle vor Ort, leicht umsetzbar; ohne eigene Rechte oder Unabhängigkeit bleibt die Wirkung auf staatliches Handeln begrenzt und ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (8868, 19, 'Antidiskriminierungs- und Interkulturalitäts-Fortbildungen in Verwaltung, Schule und Polizei (Land)', 'Land kann Fortbildungen für eigenes Personal vorschreiben; Meta-Analysen zeigen stabile Wissenszuwächse, aber schwache und abklingende Effekte auf Einstellungen und Verhalten.', 'gemischt', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'land', null, true, 'blind'),
  (8869, 19, 'Schulische Programme und Unterricht gegen Rassismus und Antisemitismus (Land)', 'Erreicht junge Menschen, bevor sich Vorurteile verfestigen; Meta-Analyse findet kleine bis mittlere Effekte, am stärksten mit Kontakt, schwächer bei ethnischen Vorurteilen und ohne Langzeitbelege.', 'gemischt', 'https://www.switchboardta.org/evidence/preventing-prejudice-and-improving-intergroup-attitudes-a-meta-analysis-of-child-and-adolescent-training-programs-3', 'land', null, true, 'blind'),
  (8870, 19, 'Landesförderung von Programmen und Projekten gegen Rassismus beenden (Land)', 'Spart Mittel und ist rechtlich möglich, streicht aber Angebote, die an verbreiteten Vorurteilen ansetzen (wenn auch mit gemischt belegter Wirkung).', 'gemischt', null, 'land', null, true, 'blind'),
  (8871, 19, 'Zivilgesellschaftliche Projekte gegen Rassismus und gruppenbezogene Menschenfeindlichkeit fördern (Land)', 'Finanzierbar und setzt an Vorurteilen an; Übersichtsarbeiten zeigen, dass meist kurze Interventionen untersucht sind und große Studien oft nur begrenzte Effekte finden.', 'gemischt', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'land', null, true, 'blind'),
  (8872, 19, 'Begegnungs- und Dialogprojekte zwischen Gruppen fördern (Land)', 'Kontakt zwischen Gruppen senkt Vorurteile in vielen Studien; neuere Auswertungen finden schwächere Effekte bei ethnischen Vorurteilen und kaum Experimente mit Erwachsenen.', 'gemischt', 'https://collaborate.princeton.edu/en/publications/the-contact-hypothesis-re-evaluated/', 'land', null, true, 'blind'),
  (8873, 19, 'Antidiskriminierungsberatungsstellen erhalten und ausbauen (Land)', 'Unterstützt Betroffene beim Umgang mit Diskriminierung und dokumentiert Fälle, lindert aber vor allem Folgen; Wirkungsstudien fehlen.', 'offen', null, 'land', null, true, 'blind'),
  (8874, 19, 'Landesstrategie oder Landesbeauftragte gegen Rassismus als Querschnittsaufgabe (Land)', 'Bündelt und koordiniert Maßnahmen gegen Vorurteile, leicht umsetzbar; die Wirkung hängt von den Einzelmaßnahmen ab und ist kaum evaluiert.', 'offen', null, 'land', null, true, 'blind'),
  (8875, 19, 'Landesaktionsplan für Akzeptanz sexueller und geschlechtlicher Vielfalt (Land)', 'Bündelt Akzeptanz-, Bildungs- und Beratungsmaßnahmen, Land ist zuständig; die Wirkung hängt von den Einzelmaßnahmen ab und ist kaum evaluiert.', 'offen', null, 'land', null, true, 'blind'),
  (8876, 19, 'Queere Themen in Unterricht, Lehrplänen und Jugendarbeit verankern (Land)', 'Setzt bei abwertenden Einstellungen junger Menschen an; Querschnittsdaten zeigen weniger Mobbing an Schulen mit inklusivem Unterricht, kausale Belege fehlen.', 'gemischt', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6478545', 'land', null, true, 'blind'),
  (8877, 19, 'Queere Beratungs-, Anlauf- und Begegnungsstrukturen fördern (Land)', 'Stützt Betroffene und schafft Sichtbarkeit, lindert aber vor allem Folgen; auf verbreitete Abwertung wirkt es nur mittelbar, Wirkungsstudien fehlen.', 'offen', null, 'land', null, true, 'blind'),
  (8878, 19, 'Erweiterung von Art. 3 GG um sexuelle und geschlechtliche Identität über den Bundesrat anstoßen (Land)', 'Rechtliche Gleichstellung kann Einstellungen verschieben; ein Land kann aber nur initiieren, die Änderung braucht Zweidrittelmehrheiten in Bundestag und Bundesrat.', 'gemischt', 'https://www.mcgill.ca/newsroom/node/158154', 'land', null, true, 'blind'),
  (8879, 19, 'Themen geschlechtlicher und sexueller Vielfalt in Kita und Schule zurückfahren (Land)', 'Landesrechtlich möglich, verringert aber Bildungsangebote, die an abwertenden Einstellungen ansetzen, statt diese abzubauen.', 'gemischt', null, 'land', null, true, 'blind'),
  (8880, 19, 'Regenbogenflaggen an öffentlichen Gebäuden und Schulen untersagen (Land)', 'Per Erlass umsetzbar; setzt nicht am Abbau abwertender Einstellungen an, sondern entfernt ein Zeichen der Anerkennung.', 'offen', null, 'land', null, true, 'blind')
on conflict (id) do update set thema_id = excluded.thema_id, name = excluded.name, begruendung = excluded.begruendung,
  evidenz = excluded.evidenz, beleg_studie_url = excluded.beleg_studie_url, ebene = excluded.ebene,
