  (8888, 19, 12, null, 'Das Allgemeine Gleichbehandlungsgesetz soll modernisiert werden, um wirksameren Schutz vor Diskriminierung zu bieten.', '{1901}', null, 1, 3, null, 'Bund ist zuständig, aber ohne Angabe, was sich am Gesetz ändern soll, ist keine deutliche Verbesserung bei Bewerbung und Einstellung abschätzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=41', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8889, 19, 12, null, 'Antidiskriminierungsstelle des Bundes stärken und zivilgesellschaftliche Beratungsangebote für Betroffene ausbauen.', '{1902}', 8858, 1, 3, null, 'Mehr Beratung hilft Betroffenen, Rechte durchzusetzen, lindert aber vor allem Folgen; auf verbreitete Vorurteile wirkt sie nur mittelbar, Wirkungsstudien fehlen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=41', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8890, 19, 12, null, 'Antidiskriminierungsberatung ausbauen, Anti-Rassismus-Beauftragte dauerhaft verankern und Nationalen Aktionsplan gegen Rassismus neu auflegen.', '{1902}', 8858, 1, 3, null, 'Mehr Beratung hilft Betroffenen, Rechte durchzusetzen, lindert aber vor allem Folgen; auf verbreitete Vorurteile wirkt sie nur mittelbar, Wirkungsstudien fehlen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=55', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8891, 19, 12, null, 'Diskriminierungsverbot im Grundgesetz auf sexuelle Orientierung und geschlechtliche Identität erweitern.', '{1903}', 8860, 1, 1, null, 'Rechtliche Gleichstellung kann Normen und Einstellungen verschieben, Schutz besteht aber schon über Art. 3 Abs. 1 GG; Verfassungsänderung braucht Zweidrittelmehrheiten in Bundestag und Bundesrat.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=49', 'https://www.mcgill.ca/newsroom/node/158154', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8892, 19, 12, null, 'Aktionsplan für queeres Leben mit der Zivilgesellschaft fortschreiben und queere Familien rechtlich gleichstellen.', '{1903}', 8862, 2, 3, null, 'Beseitigt eine konkrete rechtliche Benachteiligung, Bund ist zuständig; Studien zur Ehe-Öffnung zeigen schneller sinkende Vorurteile, teils aber Gegenreaktionen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=49', 'https://www.mcgill.ca/newsroom/node/158154', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8893, 19, 12, 'BE', 'Die Ombudsstelle des Landesantidiskriminierungsgesetzes erhält mehr Rechte (Initiativ-, Befragungsrechte, Berichtspflicht).', '{1904}', 8863, 2, 3, null, 'Schließt direkt die Schutzlücke gegenüber Behörden und Schulen; das erste Bundesland mit Gesetz verzeichnet tausende Anfragen und viele Schlichtungen, eine Wirkungsevaluation fehlt.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=48', 'https://www.berlin.de/sen/asgiva/presse/pressemitteilungen/2026/pressemitteilung.1670019.php', 'offen', '2026-10-08', false, true, 'blind'),
