  (8895, 19, 12, 'BE', 'Leitstelle Diversity in der Verwaltung; Beschäftigte werden verbindlich zu Diskriminierung geschult.', '{1904}', 8868, 1, 3, null, 'Land kann Fortbildungen für eigenes Personal vorschreiben; Meta-Analysen zeigen stabile Wissenszuwächse, aber schwache und abklingende Effekte auf Einstellungen und Verhalten.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=48', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8896, 19, 12, 'BE', 'Unabhängige Beschwerdestelle für Schulen und Kitas beim Parlament.', '{1904}', 8865, 2, 3, null, 'Gibt Betroffenen einen Weg gegen staatliche Diskriminierung; Erfahrungen mit Polizeibeauftragten zeigen Wirkung nur mit Ermittlungsbefugnissen und gezielter Ansprache Betroffener.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', 'https://www.humanistische-union.de/publikationen/vorgaenge/237-238-vorgaenge/publikation/unabhaengige-polizeibeauftragte-in-deutschland-auf-dem-weg-zum-standard-ziele-praktiken-defizite-und-moegliche-beitraege-zum-diskriminierungsschutz/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8897, 19, 12, 'BE', 'Rassismus- und queersensible Überarbeitung von Lehrplänen und Materialien, Fortbildungen und Pflichtmodule in der Ausbildung pädagogischer Fachkräfte.', '{1904,1902,1903}', null, 2, 3, null, 'Überarbeitete Lehrpläne erreichen alle Schülerinnen und Schüler, Fortbildungen das Lehrpersonal; Programme gegen Vorurteile zeigen kleine bis mittlere, nicht dauerhaft belegte Effekte.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', 'https://www.switchboardta.org/evidence/preventing-prejudice-and-improving-intergroup-attitudes-a-meta-analysis-of-child-and-adolescent-training-programs-3', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8898, 19, 12, 'BE', 'Interkulturelle Kompetenz der Polizei ausbauen und Rassismus-Sensibilisierung in Aus- und Fortbildung stärken.', '{1904}', 8868, 1, 3, null, 'Land kann Fortbildungen für eigenes Personal vorschreiben; Meta-Analysen zeigen stabile Wissenszuwächse, aber schwache und abklingende Effekte auf Einstellungen und Verhalten.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=31', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8899, 19, 12, 'BE', 'Landeskonzept Antidiskriminierung mit unabhängiger Beauftragter; Rassismusprävention gemeinsam mit den Communities weiterentwickeln.', '{1902}', 8874, 1, 3, null, 'Bündelt und koordiniert Maßnahmen gegen Vorurteile, leicht umsetzbar; die Wirkung hängt von den Einzelmaßnahmen ab und ist kaum evaluiert.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=48', null, 'offen', '2026-10-08', false, true, 'blind'),
