  (8937, 19, 14, null, 'Grundgesetz Artikel 3 um die sexuelle Identität ergänzen.', '{1903}', 8860, 1, 1, null, 'Rechtliche Gleichstellung kann Normen und Einstellungen verschieben, Schutz besteht aber schon über Art. 3 Abs. 1 GG; Verfassungsänderung braucht Zweidrittelmehrheiten in Bundestag und Bundesrat.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=25', 'https://www.mcgill.ca/newsroom/node/158154', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8938, 19, 14, null, 'Familienrecht modernisieren, etwa Elternschaftsvereinbarungen in Regenbogenfamilien und Adoption für unverheiratete Paare ermöglichen.', '{1903}', 8862, 2, 3, null, 'Beseitigt eine konkrete rechtliche Benachteiligung, Bund ist zuständig; Studien zur Ehe-Öffnung zeigen schneller sinkende Vorurteile, teils aber Gegenreaktionen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=31', 'https://www.mcgill.ca/newsroom/node/158154', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8939, 19, 14, null, 'IHRA-Antisemitismusdefinition in staatlichen Behörden etablieren und zur Grundlage von Fortbildungen von Beamten machen.', '{1904}', 8859, 1, 3, null, 'Für eigene Behörden leicht umsetzbar; Meta-Analysen zeigen stabile Wissenszuwächse, aber schwache und abklingende Effekte auf Einstellungen und Verhalten.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=26', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8940, 19, 14, 'BE', 'Verbindliche Bildungsprogramme an Schulen gegen Antisemitismus mit jüdischen Perspektiven und Begegnungsformaten, die Vorurteile abbauen.', '{1902}', 8869, 2, 3, null, 'Erreicht junge Menschen, bevor sich Vorurteile verfestigen; Meta-Analyse findet kleine bis mittlere Effekte, am stärksten mit Kontakt, schwächer bei ethnischen Vorurteilen und ohne Langzeitbelege.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=79', 'https://www.switchboardta.org/evidence/preventing-prejudice-and-improving-intergroup-attitudes-a-meta-analysis-of-child-and-adolescent-training-programs-3', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8941, 19, 14, 'BE', 'Queere Netzwerke in Landesunternehmen, Verwaltung und Wirtschaft fördern.', '{1903}', 8877, 1, 3, null, 'Stützt Betroffene und schafft Sichtbarkeit, lindert aber vor allem Folgen; auf verbreitete Abwertung wirkt es nur mittelbar, Wirkungsstudien fehlen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=82', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8942, 19, 14, 'BE', 'Schutzunterkünfte und Beratungsangebote für queere Menschen, besonders Geflüchtete und Menschen mit Migrationsgeschichte, stärker unterstützen.', '{1903}', 8877, 1, 3, null, 'Stützt Betroffene und schafft Sichtbarkeit, lindert aber vor allem Folgen; auf verbreitete Abwertung wirkt es nur mittelbar, Wirkungsstudien fehlen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=82', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8943, 19, 14, 'BE', 'Beweislastumkehr-Vermutungsregel im Landesantidiskriminierungsgesetz abschaffen.', '{1904}', 8864, 0, 3, null, 'Rechtlich möglich, vergrößert aber die Schutzlücke gegenüber staatlichem Handeln, statt sie zu schließen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=67', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8944, 19, 14, 'ST', 'In Jugendarbeit und Schule soll Diskriminierung wegen Herkunft, Religion oder sexueller Orientierung durch Aufklärung für Toleranz und Akzeptanz entgegengewirkt werden.', '{1902,1903}', 8869, 2, 3, null, 'Erreicht junge Menschen, bevor sich Vorurteile verfestigen; Meta-Analyse findet kleine bis mittlere Effekte, am stärksten mit Kontakt, schwächer bei ethnischen Vorurteilen und ohne Langzeitbelege.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=37', 'https://www.switchboardta.org/evidence/preventing-prejudice-and-improving-intergroup-attitudes-a-meta-analysis-of-child-and-adolescent-training-programs-3', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8945, 19, 14, 'ST', 'Feste Ansprechpersonen für Antidiskriminierung in der Polizei aufbauen und konsequente, nachhaltige Fortbildung einfordern.', '{1904}', 8867, 1, 3, null, 'Niedrigschwellige Anlaufstelle vor Ort, leicht umsetzbar; ohne eigene Rechte oder Unabhängigkeit bleibt die Wirkung auf staatliches Handeln begrenzt und ist kaum untersucht.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=37', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8946, 19, 14, 'ST', 'Verwaltungshandeln soll verschiedene Geschlechtsidentitäten berücksichtigen und von Selbstbestimmung geprägt sein; Geschlechtsangabe nur wo nötig erfassen.', '{1903}', null, 1, 3, null, 'Respektvolle Verwaltungspraxis zur Geschlechtsidentität vermeidet Herabsetzung im Behördenkontakt; auf verbreitete Einstellungen wirkt sie kaum, Belege fehlen.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=37', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8947, 19, 15, null, 'Gesetzliche Antidiskriminierungsregeln im Zivilrecht werden abgelehnt; Vertragsabschlussfreiheit soll Vorrang haben.', '{1901}', null, 0, 0, null, 'Verzicht auf Diskriminierungsschutz bei Verträgen und Einstellung hilft Betroffenen nicht; EU-Gleichbehandlungsrichtlinien verpflichten Deutschland zu solchen Regeln.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=134', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8948, 19, 15, 'BE', 'Das Landesantidiskriminierungsgesetz soll sofort aufgehoben werden (Abschaffung des Rechtsschutzes gegen Diskriminierung durch staatliches Handeln).', '{1904}', 8864, 0, 3, null, 'Rechtlich möglich, vergrößert aber die Schutzlücke gegenüber staatlichem Handeln, statt sie zu schließen.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=13', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8949, 19, 15, 'BE', 'Das Beauftragtenwesen, auch Antidiskriminierungsbeauftragte, soll abgeschafft und das Geld für Familienförderung verwendet werden.', '{1904}', 8866, 0, 3, null, 'Spart Mittel und ist rechtlich möglich, nimmt Betroffenen aber Anlaufstellen gegen Diskriminierung durch staatliche Stellen.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=60', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8950, 19, 15, 'BE', 'Die öffentliche Förderung von Meldestellen für diskriminierende Vorfälle wird beendet; sie sollen sich privat finanzieren.', '{1902}', 8870, 0, 3, null, 'Spart Mittel und ist rechtlich möglich, streicht aber Angebote, die an verbreiteten Vorurteilen ansetzen (wenn auch mit gemischt belegter Wirkung).', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=77', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (8951, 19, 15, 'BE', 'Antisemitismusprävention im Schulunterricht ausbauen und verankern.', '{1902}', 8869, 2, 3, null, 'Erreicht junge Menschen, bevor sich Vorurteile verfestigen; Meta-Analyse findet kleine bis mittlere Effekte, am stärksten mit Kontakt, schwächer bei ethnischen Vorurteilen und ohne Langzeitbelege.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=24', 'https://www.switchboardta.org/evidence/preventing-prejudice-and-improving-intergroup-attitudes-a-meta-analysis-of-child-and-adolescent-training-programs-3', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8952, 19, 15, 'MV', 'Das Selbstbestimmungsgesetz (Änderung des Geschlechtseintrags) soll über den Bundesrat aufgehoben werden.', '{1903}', null, 0, 1, null, 'Baut keine Abwertung ab, sondern erschwert die rechtliche Anerkennung der Geschlechtsidentität; ein Land kann die Aufhebung nur über den Bundesrat beantragen.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=20', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8953, 19, 15, 'MV', 'Nicht hoheitliche Flaggen wie Regenbogenflaggen vor öffentlichen Einrichtungen werden untersagt.', '{1903}', 8880, 0, 3, null, 'Per Erlass umsetzbar; setzt nicht am Abbau abwertender Einstellungen an, sondern entfernt ein Zeichen der Anerkennung.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=42', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8954, 19, 15, 'MV', 'Lehrinhalte sollen sich an der Mehrheit orientieren und ein bestimmtes Familienbild vermitteln; Gender-Programme an Schulen sind unerwünscht.', '{1903}', 8879, 0, 3, null, 'Landesrechtlich möglich, verringert aber Bildungsangebote, die an abwertenden Einstellungen ansetzen, statt diese abzubauen.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=26', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (8955, 19, 15, 'MV', 'Landesförderung für Vereine und Initiativen, die Regierungs- und Migrationskritik mit Rassismus gleichsetzen, wird beendet.', '{1902}', 8870, 0, 3, null, 'Spart Mittel und ist rechtlich möglich, streicht aber Angebote, die an verbreiteten Vorurteilen ansetzen (wenn auch mit gemischt belegter Wirkung).', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=47', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (8956, 19, 15, 'MV', 'Schulungen zu interkultureller Kompetenz in der Verwaltung werden beendet.', '{1904}', null, 0, 3, null, 'Rechtlich ohne Weiteres möglich, streicht aber Schulungen, die (mit gemischt belegter Wirkung) diskriminierendes Verwaltungshandeln verringern sollen.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=53', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (8957, 19, 15, 'ST', 'Landesförderung des Schulprogramms gegen Rassismus einstellen', '{1902}', 8870, 0, 3, null, 'Spart Mittel und ist rechtlich möglich, streicht aber Angebote, die an verbreiteten Vorurteilen ansetzen (wenn auch mit gemischt belegter Wirkung).', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=77', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (8958, 19, 15, 'ST', 'Regenbogenflagge an Schulen von offizieller Seite nicht mehr zeigen (Runderlass)', '{1903}', 8880, 0, 3, null, 'Per Erlass umsetzbar; setzt nicht am Abbau abwertender Einstellungen an, sondern entfernt ein Zeichen der Anerkennung.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=77', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8959, 19, 15, 'ST', 'Kampagnen und Programme zu sexuellen Themen für Kinder vor der Pubertät einstellen; in der Kita Familie aus Mann und Frau als Normalform voraussetzen', '{1903}', 8879, 0, 3, null, 'Landesrechtlich möglich, verringert aber Bildungsangebote, die an abwertenden Einstellungen ansetzen, statt diese abzubauen.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=22', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (8960, 19, 16, null, 'Anonymisierte Bewerbungsverfahren für gleiche Ausbildungschancen', '{1901}', 8856, 2, 3, null, 'Setzt an der Vorauswahl an, in der etwa Name oder Kopftuchfoto zu Absagen führen; das deutsche Pilotprojekt fand bessere Einladungschancen, ein französisches Feldexperiment dagegen Nachteile für Minderheiten.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=40', 'https://www.povertyactionlab.org/evaluation/cv-anonymes', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8961, 19, 16, null, 'Quoten für von Diskriminierung Betroffene auch auf dem privaten Arbeitsmarkt', '{1901}', null, 2, 1, null, 'Vorgaben für Arbeitgeber erhöhten in den USA dauerhaft den Anteil Schwarzer Beschäftigter; starre Quoten nach Herkunft stoßen aber auf Art. 3 Abs. 3 GG, EU-Recht und Datenschutz.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=53', 'https://ftp.aeaweb.org/research/can-temporary-affirmative-action-policies-have-lasting-effects', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8962, 19, 16, null, 'Reform des Gleichbehandlungsgesetzes: längere Klagefristen, Verbandsklage, Einbezug staatlichen Handelns', '{1904}', 8857, 2, 2, null, 'Längere Fristen und Verbandsklage erleichtern die Durchsetzung bei Bewerbung und gegenüber Behörden; Wirkung auf die Häufigkeit von Diskriminierung kaum untersucht, Bundeskompetenz für Landesbehörden begrenzt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=53', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8963, 19, 16, null, 'Gesetzliches Verbot rassistischer Polizeikontrollen und Antidiskriminierungsschulungen im öffentlichen Dienst', '{1904}', null, 2, 3, null, 'Ethnisches Profiling bei Kontrollen ist laut EU-Grundrechteagentur verbreitet; ein Verbot und der Wegfall anlassloser Kontrollen setzen direkt dort an, für die Bundespolizei ist der Bund zuständig, Wirkungsstudien fehlen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=53', 'https://fra.europa.eu/en/news/2023/stop-discrimination-and-ethnic-profiling-europe', 'offen', '2026-10-08', false, true, 'blind'),
  (8964, 19, 16, null, 'Stärkere, langfristige Förderung von Opferberatungen und Bündnissen gegen Rassismus per Demokratiefördergesetz', '{1902}', null, 1, 2, null, 'Langfristige Förderung stabilisiert Präventions- und Beratungsarbeit; Effekte solcher Projekte auf Vorurteile sind begrenzt belegt, die Bundeskompetenz für ein Demokratiefördergesetz ist umstritten.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=51', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8965, 19, 16, null, 'Grundgesetz Art. 3 um sexuelle Orientierung und geschlechtliche Identität erweitern', '{1903}', 8860, 1, 1, null, 'Rechtliche Gleichstellung kann Normen und Einstellungen verschieben, Schutz besteht aber schon über Art. 3 Abs. 1 GG; Verfassungsänderung braucht Zweidrittelmehrheiten in Bundestag und Bundesrat.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=47', 'https://www.mcgill.ca/newsroom/node/158154', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8966, 19, 16, null, 'Ausfinanzierter Aktionsplan gegen queerfeindliche Diskriminierung und bundesweites Antidiskriminierungsgesetz', '{1903}', 8861, 1, 3, null, 'Bündelt Akzeptanz-, Bildungs- und Beratungsmaßnahmen und ist finanzierbar; die Wirkung hängt von den Einzelmaßnahmen ab und ist kaum evaluiert.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=47', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8967, 19, 16, null, 'Queere Orte schützen, queere Jugendarbeit als kommunale Pflichtaufgabe', '{1903}', null, 1, 1, null, 'Erhält Treffpunkte, lindert aber vor allem Folgen; der Bund darf Kommunen keine Pflichtaufgaben übertragen (Art. 84 Abs. 1 GG), Mietschutz für einzelne Orte ist rechtlich ungeklärt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=47', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8968, 19, 16, 'BE', 'Rassismusbekämpfung als Querschnittsaufgabe aller Senatsverwaltungen mit eigenen Strategien, Geld und Personal; Arbeit dauerhaft sichern', '{1902}', 8874, 1, 3, null, 'Bündelt und koordiniert Maßnahmen gegen Vorurteile, leicht umsetzbar; die Wirkung hängt von den Einzelmaßnahmen ab und ist kaum evaluiert.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=268', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8969, 19, 16, 'BE', 'Ressortübergreifende Strategie gegen antimuslimischen Rassismus, auch für den digitalen Raum, mit Ansprechperson', '{1902}', 8874, 1, 3, null, 'Bündelt und koordiniert Maßnahmen gegen Vorurteile, leicht umsetzbar; die Wirkung hängt von den Einzelmaßnahmen ab und ist kaum evaluiert.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=272', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8970, 19, 16, 'BE', 'Pflichtfortbildungen zu Diskriminierung und Rassismus für Beschäftigte im öffentlichen Dienst, Sozialbereich und Sicherheitspersonal', '{1902}', 8868, 1, 3, null, 'Land kann Fortbildungen für eigenes Personal vorschreiben; Meta-Analysen zeigen stabile Wissenszuwächse, aber schwache und abklingende Effekte auf Einstellungen und Verhalten.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=327', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8971, 19, 16, 'BE', 'Landesantidiskriminierungsgesetz um weitere Tatbestände ergänzen und Ombudsstelle stärken, mit Informationskampagne', '{1904}', 8863, 2, 3, null, 'Schließt direkt die Schutzlücke gegenüber Behörden und Schulen; das erste Bundesland mit Gesetz verzeichnet tausende Anfragen und viele Schlichtungen, eine Wirkungsevaluation fehlt.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=270', 'https://www.berlin.de/sen/asgiva/presse/pressemitteilungen/2026/pressemitteilung.1670019.php', 'offen', '2026-10-08', false, true, 'blind'),
  (8972, 19, 16, 'BE', 'Unabhängige Beschwerdestelle für Diskriminierung an Schulen mit Akteneinsichts- und Durchgriffsrechten', '{1904}', 8865, 2, 3, null, 'Gibt Betroffenen einen Weg gegen staatliche Diskriminierung; Erfahrungen mit Polizeibeauftragten zeigen Wirkung nur mit Ermittlungsbefugnissen und gezielter Ansprache Betroffener.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=162', 'https://www.humanistische-union.de/publikationen/vorgaenge/237-238-vorgaenge/publikation/unabhaengige-polizeibeauftragte-in-deutschland-auf-dem-weg-zum-standard-ziele-praktiken-defizite-und-moegliche-beitraege-zum-diskriminierungsschutz/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8973, 19, 16, 'BE', 'Gesamten öffentlichen Dienst diskriminierungskritisch aufstellen und schulen, inklusive Einstellungsverfahren', '{1904}', 8868, 1, 3, null, 'Land kann Fortbildungen für eigenes Personal vorschreiben; Meta-Analysen zeigen stabile Wissenszuwächse, aber schwache und abklingende Effekte auf Einstellungen und Verhalten.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=268', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8974, 19, 16, 'BE', 'Qualifizierte Verantwortliche für geschlechtliche und sexuelle Vielfalt an jeder Schule, externe queere Bildungsarbeit stärken, Vielfalt in Rahmenlehrplänen', '{1903}', 8876, 2, 3, null, 'Setzt bei abwertenden Einstellungen junger Menschen an; Querschnittsdaten zeigen weniger Mobbing an Schulen mit inklusivem Unterricht, kausale Belege fehlen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=218', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6478545', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8975, 19, 16, 'BE', 'Landesinitiative für Akzeptanz geschlechtlicher und sexueller Vielfalt evaluieren, weiterentwickeln, ins Parlament holen; queerer Beirat', '{1903}', 8875, 1, 3, null, 'Bündelt Akzeptanz-, Bildungs- und Beratungsmaßnahmen, Land ist zuständig; die Wirkung hängt von den Einzelmaßnahmen ab und ist kaum evaluiert.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=216', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8976, 19, 16, 'MV', 'Antidiskriminierungsberatungsstellen erhalten und ausbauen', '{1902}', 8873, 1, 3, null, 'Unterstützt Betroffene beim Umgang mit Diskriminierung und dokumentiert Fälle, lindert aber vor allem Folgen; Wirkungsstudien fehlen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=16', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8977, 19, 16, 'MV', 'Eigenes Landesantidiskriminierungsgesetz auf den Weg bringen', '{1904}', 8863, 2, 3, null, 'Schließt direkt die Schutzlücke gegenüber Behörden und Schulen; das erste Bundesland mit Gesetz verzeichnet tausende Anfragen und viele Schlichtungen, eine Wirkungsevaluation fehlt.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=16', 'https://www.berlin.de/sen/asgiva/presse/pressemitteilungen/2026/pressemitteilung.1670019.php', 'offen', '2026-10-08', false, true, 'blind'),
  (8978, 19, 16, 'MV', 'Fortbildungen zu Antidiskriminierung und strukturellem Rassismus für alle Beschäftigten der Justiz verankern', '{1904}', 8868, 1, 3, null, 'Land kann Fortbildungen für eigenes Personal vorschreiben; Meta-Analysen zeigen stabile Wissenszuwächse, aber schwache und abklingende Effekte auf Einstellungen und Verhalten.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=24', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8979, 19, 16, 'MV', 'Landesaktionsplan für Akzeptanz sexueller und geschlechtlicher Vielfalt ausfinanzieren und weiterführen', '{1903}', 8875, 1, 3, null, 'Bündelt Akzeptanz-, Bildungs- und Beratungsmaßnahmen, Land ist zuständig; die Wirkung hängt von den Einzelmaßnahmen ab und ist kaum evaluiert.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=16', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8980, 19, 16, 'MV', 'Queeres Leben im Rahmenplan von Schulen verankern', '{1903}', 8876, 2, 3, null, 'Setzt bei abwertenden Einstellungen junger Menschen an; Querschnittsdaten zeigen weniger Mobbing an Schulen mit inklusivem Unterricht, kausale Belege fehlen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=16', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6478545', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8981, 19, 16, 'ST', 'Landesaktionsprogramm für die Akzeptanz von LSBTI+ zusammen mit der Community ausbauen und finanziell ausstatten, besonders im ländlichen Raum, in Jugendbildung und Seniorenarbeit.', '{1903}', 8875, 1, 3, null, 'Bündelt Akzeptanz-, Bildungs- und Beratungsmaßnahmen, Land ist zuständig; die Wirkung hängt von den Einzelmaßnahmen ab und ist kaum evaluiert.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=24', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8982, 19, 16, 'ST', 'Queere Themen in allen Stationen des Bildungsweges behandeln; Lehr- und Erziehungskräfte schon in Ausbildung dafür befähigen, Lehrpläne anpassen.', '{1903}', 8876, 2, 3, null, 'Setzt bei abwertenden Einstellungen junger Menschen an; Querschnittsdaten zeigen weniger Mobbing an Schulen mit inklusivem Unterricht, kausale Belege fehlen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=25', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6478545', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8983, 19, 16, 'ST', 'LSBTIQ+-Landeskoordinierungsstellen weiter ausbauen und ihre Sichtbarkeit erhöhen.', '{1903}', 8877, 1, 3, null, 'Stützt Betroffene und schafft Sichtbarkeit, lindert aber vor allem Folgen; auf verbreitete Abwertung wirkt es nur mittelbar, Wirkungsstudien fehlen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=24', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8984, 19, 16, 'ST', 'Bundesratsinitiative, um sexuelle und geschlechtliche Identität als Merkmal in den Gleichheitsartikel des Grundgesetzes aufzunehmen.', '{1903}', 8878, 1, 1, null, 'Rechtliche Gleichstellung kann Einstellungen verschieben; ein Land kann aber nur initiieren, die Änderung braucht Zweidrittelmehrheiten in Bundestag und Bundesrat.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=24', 'https://www.mcgill.ca/newsroom/node/158154', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8985, 19, 16, 'ST', 'Weiterbildungen zu interkultureller Kompetenz für alle relevanten Beschäftigten im öffentlichen Dienst.', '{1904}', 8868, 1, 3, null, 'Land kann Fortbildungen für eigenes Personal vorschreiben; Meta-Analysen zeigen stabile Wissenszuwächse, aber schwache und abklingende Effekte auf Einstellungen und Verhalten.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=98', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8986, 19, 16, 'ST', 'Regelmäßige Fortbildungen der Polizei zu Menschenrechten und interkultureller Kompetenz.', '{1904}', 8868, 1, 3, null, 'Land kann Fortbildungen für eigenes Personal vorschreiben; Meta-Analysen zeigen stabile Wissenszuwächse, aber schwache und abklingende Effekte auf Einstellungen und Verhalten.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=128', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8987, 19, 16, 'ST', 'Lehrpläne greifen die Vielfalt der Kulturen im Unterricht auf, um gegenseitiges Lernen zu fördern.', '{1902}', 8869, 2, 3, null, 'Erreicht junge Menschen, bevor sich Vorurteile verfestigen; Meta-Analyse findet kleine bis mittlere Effekte, am stärksten mit Kontakt, schwächer bei ethnischen Vorurteilen und ohne Langzeitbelege.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=99', 'https://www.switchboardta.org/evidence/preventing-prejudice-and-improving-intergroup-attitudes-a-meta-analysis-of-child-and-adolescent-training-programs-3', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8988, 19, 16, 'ST', 'Interkulturelle Kulturarbeit und migrantische Kunst- und Kulturszenen über regionale Netzwerke fördern.', '{1902}', 8872, 2, 3, null, 'Kontakt zwischen Gruppen senkt Vorurteile in vielen Studien; neuere Auswertungen finden schwächere Effekte bei ethnischen Vorurteilen und kaum Experimente mit Erwachsenen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=70', 'https://collaborate.princeton.edu/en/publications/the-contact-hypothesis-re-evaluated/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8989, 19, 17, 'BE', 'Kulturelle Begegnungen und integrative Stadtteilarbeit fördern, Nachbarschaftsprojekte, interkulturelle Feste und Sportvereine finanzieren, um Vorbehalte abzubauen.', '{1902}', 8872, 2, 3, null, 'Kontakt zwischen Gruppen senkt Vorurteile in vielen Studien; neuere Auswertungen finden schwächere Effekte bei ethnischen Vorurteilen und kaum Experimente mit Erwachsenen.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=37', 'https://collaborate.princeton.edu/en/publications/the-contact-hypothesis-re-evaluated/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8990, 19, 17, 'ST', 'Fortbildungen zur Sensibilisierung in staatlichen Institutionen im Zusammenhang mit dem Schutz der Rechte gleichgeschlechtlicher Ehepaare.', '{1904}', 8868, 1, 3, null, 'Land kann Fortbildungen für eigenes Personal vorschreiben; Meta-Analysen zeigen stabile Wissenszuwächse, aber schwache und abklingende Effekte auf Einstellungen und Verhalten.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=38', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8991, 19, 17, 'ST', 'Staatliche und kommunale Einrichtungen sollen keine Konzepte zu Geschlecht, Sexualität oder Identität gegen den Willen der Eltern einführen oder fördern.', '{1903}', 8879, 0, 3, null, 'Landesrechtlich möglich, verringert aber Bildungsangebote, die an abwertenden Einstellungen ansetzen, statt diese abzubauen.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=39', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (8992, 19, 18, null, 'Anonymisierte Bewerbungsverfahren einführen und fördern, um Diskriminierung bei der Einstellung zu verringern.', '{1901}', 8856, 2, 3, null, 'Setzt an der Vorauswahl an, in der etwa Name oder Kopftuchfoto zu Absagen führen; das deutsche Pilotprojekt fand bessere Einladungschancen, ein französisches Feldexperiment dagegen Nachteile für Minderheiten.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=147', 'https://www.povertyactionlab.org/evaluation/cv-anonymes', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8993, 19, 18, null, 'Antidiskriminierungsstelle des Bundes erweitern: mehr Anlaufstellen, schnellere Verfahren, mehr Beratung und Begleitung für Betroffene.', '{1902}', 8858, 1, 3, null, 'Mehr Beratung hilft Betroffenen, Rechte durchzusetzen, lindert aber vor allem Folgen; auf verbreitete Vorurteile wirkt sie nur mittelbar, Wirkungsstudien fehlen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=141', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8994, 19, 18, null, 'Bildungsangebote und Programme für Kinder und Jugendliche gegen Rassismus und Vorurteile, mit Austausch zwischen unterschiedlichen Hintergründen.', '{1902}', null, 2, 2, null, 'Programme mit Begegnung wirken laut Meta-Analyse am besten gegen Vorurteile Jugendlicher, schwächer bei ethnischen Vorurteilen; Bildung ist Ländersache, der Bund kann fördern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=143', 'https://www.switchboardta.org/evidence/preventing-prejudice-and-improving-intergroup-attitudes-a-meta-analysis-of-child-and-adolescent-training-programs-3', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8995, 19, 18, null, 'Geschlechtsidentität und sexuelle Vielfalt als Diskriminierungsmerkmale ins Grundgesetz aufnehmen.', '{1903}', 8860, 1, 1, null, 'Rechtliche Gleichstellung kann Normen und Einstellungen verschieben, Schutz besteht aber schon über Art. 3 Abs. 1 GG; Verfassungsänderung braucht Zweidrittelmehrheiten in Bundestag und Bundesrat.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=148', 'https://www.mcgill.ca/newsroom/node/158154', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8996, 19, 18, null, 'Queere Lebensweisen und Identitäten in Schulen und Universitäten gemeinsam mit zivilgesellschaftlichen Organisationen thematisieren.', '{1903}', null, 2, 2, null, 'Setzt bei Einstellungen junger Menschen an, Querschnittsdaten zeigen weniger Mobbing bei inklusivem Unterricht; Schulen sind Ländersache, der Bund kann nur über Förderung beitragen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=149', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6478545', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8997, 19, 18, null, 'Unabhängige Kontrollstellen für Polizei, Verwaltung und Justiz sowie Antidiskriminierungsbeauftragte als Ansprechpersonen in Behörden.', '{1904}', null, 2, 2, null, 'Unabhängige Kontrolle gibt Betroffenen einen Weg gegen staatliche Diskriminierung; Erfahrungen zeigen Wirkung nur mit Befugnissen, eine Kontrollstelle für die Justiz stößt an die richterliche Unabhängigkeit.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=143', 'https://www.humanistische-union.de/publikationen/vorgaenge/237-238-vorgaenge/publikation/unabhaengige-polizeibeauftragte-in-deutschland-auf-dem-weg-zum-standard-ziele-praktiken-defizite-und-moegliche-beitraege-zum-diskriminierungsschutz/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8998, 19, 18, null, 'Verpflichtende Schulungen für Behördenmitarbeitende zu Sensibilität und Antidiskriminierung.', '{1904}', 8859, 1, 3, null, 'Für eigene Behörden leicht umsetzbar; Meta-Analysen zeigen stabile Wissenszuwächse, aber schwache und abklingende Effekte auf Einstellungen und Verhalten.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=137', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8999, 19, 18, 'BE', 'Landesstrategien gegen Queerfeindlichkeit sowie gegen Rassismus konsequent umsetzen und die Prävention gegen Diskriminierung in Bezirken ausbauen.', '{1902,1903}', 8874, 1, 3, null, 'Bündelt und koordiniert Maßnahmen gegen Vorurteile, leicht umsetzbar; die Wirkung hängt von den Einzelmaßnahmen ab und ist kaum evaluiert.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=74', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9000, 19, 18, 'BE', 'Queere Kultur- und Begegnungsorte fördern und queere Sichtbarkeit im öffentlichen Raum stärken, auch durch Veranstaltungen zum Pride Month in allen Bezirken.', '{1903}', 8877, 1, 3, null, 'Stützt Betroffene und schafft Sichtbarkeit, lindert aber vor allem Folgen; auf verbreitete Abwertung wirkt es nur mittelbar, Wirkungsstudien fehlen.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=86', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9001, 19, 18, 'BE', 'Kolonialgeschichte im Humboldt Forum kritisch aufarbeiten, um Ungleichheiten und Rassismus entgegenzuwirken.', '{1902}', 8871, 1, 3, null, 'Finanzierbar und setzt an Vorurteilen an; Übersichtsarbeiten zeigen, dass meist kurze Interventionen untersucht sind und große Studien oft nur begrenzte Effekte finden.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=111', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9002, 19, 18, 'BE', 'Polizei verpflichtend regelmäßig zu Rassismus und Diskriminierung schulen.', '{1904}', 8868, 1, 3, null, 'Land kann Fortbildungen für eigenes Personal vorschreiben; Meta-Analysen zeigen stabile Wissenszuwächse, aber schwache und abklingende Effekte auf Einstellungen und Verhalten.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=77', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9003, 19, 18, 'BE', 'Bürger- und Polizeibeauftragten als anonyme Meldestelle mit Ermittlungsbefugnissen stärken, damit rassistische und queerfeindliche Äußerungen im Dienst sanktioniert werden.', '{1904}', 8865, 2, 3, null, 'Gibt Betroffenen einen Weg gegen staatliche Diskriminierung; Erfahrungen mit Polizeibeauftragten zeigen Wirkung nur mit Ermittlungsbefugnissen und gezielter Ansprache Betroffener.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=77', 'https://www.humanistische-union.de/publikationen/vorgaenge/237-238-vorgaenge/publikation/unabhaengige-polizeibeauftragte-in-deutschland-auf-dem-weg-zum-standard-ziele-praktiken-defizite-und-moegliche-beitraege-zum-diskriminierungsschutz/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9004, 19, 18, 'MV', 'Unabhängige Landesantidiskriminierungsstelle für Beratung, Monitoring und Prävention gegen Diskriminierung aufbauen.', '{1904}', 8865, 2, 3, null, 'Gibt Betroffenen einen Weg gegen staatliche Diskriminierung; Erfahrungen mit Polizeibeauftragten zeigen Wirkung nur mit Ermittlungsbefugnissen und gezielter Ansprache Betroffener.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=17', 'https://www.humanistische-union.de/publikationen/vorgaenge/237-238-vorgaenge/publikation/unabhaengige-polizeibeauftragte-in-deutschland-auf-dem-weg-zum-standard-ziele-praktiken-defizite-und-moegliche-beitraege-zum-diskriminierungsschutz/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9005, 19, 18, 'MV', 'Verbindliche, regelmäßige Antidiskriminierungs-Fortbildungen für Mitarbeitende in Verwaltung, Bildungseinrichtungen und Polizei.', '{1904}', 8868, 1, 3, null, 'Land kann Fortbildungen für eigenes Personal vorschreiben; Meta-Analysen zeigen stabile Wissenszuwächse, aber schwache und abklingende Effekte auf Einstellungen und Verhalten.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=18', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9006, 19, 18, 'MV', 'Antidiskriminierungsbeauftragte als Ansprechpersonen in Schulen, Behörden und Polizei einsetzen.', '{1904}', 8867, 1, 3, null, 'Niedrigschwellige Anlaufstelle vor Ort, leicht umsetzbar; ohne eigene Rechte oder Unabhängigkeit bleibt die Wirkung auf staatliches Handeln begrenzt und ist kaum untersucht.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=18', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9007, 19, 18, 'ST', 'Landesantidiskriminierungsgesetz einführen und unabhängige Landes-Antidiskriminierungsstelle mit Beratungs-, Monitoring- und Präventionsauftrag stärken.', '{1904}', 8863, 2, 3, null, 'Schließt direkt die Schutzlücke gegenüber Behörden und Schulen; das erste Bundesland mit Gesetz verzeichnet tausende Anfragen und viele Schlichtungen, eine Wirkungsevaluation fehlt.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=131', 'https://www.berlin.de/sen/asgiva/presse/pressemitteilungen/2026/pressemitteilung.1670019.php', 'offen', '2026-10-08', false, true, 'blind'),
  (9008, 19, 18, 'ST', 'Verbindliche Fortbildungen zur Antidiskriminierung in Verwaltung, Schule und Polizei.', '{1904}', 8868, 1, 3, null, 'Land kann Fortbildungen für eigenes Personal vorschreiben; Meta-Analysen zeigen stabile Wissenszuwächse, aber schwache und abklingende Effekte auf Einstellungen und Verhalten.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=131', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9009, 19, 18, 'ST', 'Schulprogramme gegen Rassismus systematisch stärken und flächendeckend ausbauen.', '{1902}', 8869, 2, 3, null, 'Erreicht junge Menschen, bevor sich Vorurteile verfestigen; Meta-Analyse findet kleine bis mittlere Effekte, am stärksten mit Kontakt, schwächer bei ethnischen Vorurteilen und ohne Langzeitbelege.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=131', 'https://www.switchboardta.org/evidence/preventing-prejudice-and-improving-intergroup-attitudes-a-meta-analysis-of-child-and-adolescent-training-programs-3', 'gemischt', '2026-10-08', false, true, 'blind');

